mapper.select:
SELECT * FROM (
    SELECT cm.message_id, cm.room_id, cm.sender_id, m.nickname AS sender_name, cm.content, cm.created_at
    FROM chat_message cm
    JOIN member m ON m.member_id = cm.sender_id
    WHERE cm.room_id = #{roomId}

        AND cm.message_id < #{beforeId}

    ORDER BY cm.message_id DESC
    LIMIT #{size}
) recent
ORDER BY message_id
